#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int MAXN = 14;
const int MAX_NODES = 7100;
const ll INF = 1e9;

struct Edge {
    int from, to;
    ll flow, cap;
};

struct Dinic {
    int s, t;
    vector<Edge> edges;
    vector<int> adj[MAX_NODES];
    int level[MAX_NODES], ptr[MAX_NODES];

    void init() {
        edges.clear();
        for (int i = 0; i < MAX_NODES; ++i) adj[i].clear();
    }

    void add_edge(int u, int v, ll capacity) {
        edges.push_back({u, v, 0, capacity});
        edges.push_back({v, u, 0, 0});
        adj[u].push_back((int)edges.size() - 2);
        adj[v].push_back((int)edges.size() - 1);
    }

    bool bfs() {
        memset(level, -1, sizeof(level));
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int id : adj[u]) {
                Edge& e = edges[id];
                if (level[e.to] == -1 && e.cap > e.flow) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    ll dfs(int u, ll flow) {
        if (u == t || flow == 0) return flow;
        for (int& i = ptr[u]; i < (int)adj[u].size(); ++i) {
            int id = adj[u][i];
            Edge& e = edges[id];
            if (level[e.to] == level[u] + 1 && e.cap > e.flow) {
                ll pushed = dfs(e.to, min(flow, e.cap - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[id ^ 1].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll max_flow() {
        ll result = 0;
        while (bfs()) {
            memset(ptr, 0, sizeof(ptr));
            while (ll pushed = dfs(s, INF)) {
                result += pushed;
            }
        }
        return result;
    }
};

Dinic mf;
char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
bool vis[MAXN][MAXN];
int dist_grid[MAXN][MAXN];
int n, T;
int target_node[103];

int idx(int t, int x, int y) {
    return t * n * n + (x - 1) * n + y;
}

void bfs(int sx, int sy) {
    queue<tuple<int, int, int>> q;
    for (int i = 0; i < MAXN; ++i)
        for (int j = 0; j < MAXN; ++j)
            dist_grid[i][j] = 111;

    dist_grid[sx][sy] = 0;
    q.emplace(sx, sy, 0);
    int dx[] = {1, 0, 0, -1}, dy[] = {0, 1, -1, 0};

    while (!q.empty()) {
        auto [x, y, d] = q.front(); q.pop();
        if (vis[x][y]) continue;
        vis[x][y] = true;
        dist_grid[x][y] = d;
        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 1 || nx > n || ny < 1 || ny > n || vis[nx][ny] || grid1[nx][ny] == 'Y')
                continue;
            q.emplace(nx, ny, d + 1);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> T;
    for (int i = 1; i <= n; ++i) cin >> (grid1[i] + 1);
    for (int i = 1; i <= n; ++i) cin >> (grid2[i] + 1);

    mf.init();
    mf.s = 0;
    mf.t = MAX_NODES - 2;

    int sx = 0, sy = 0;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') {
                sx = i; sy = j;
                break;
            }
        }
    }

    for (int i = 1; i <= n * n; ++i)
        target_node[i] = MAX_NODES - 3 - (n * n - i);

    bfs(sx, sy);

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (isdigit(grid1[i][j]))
                mf.add_edge(mf.s, idx(0, i, j), grid1[i][j] - '0');
            if (isdigit(grid2[i][j]))
                mf.add_edge(target_node[idx(0, i, j)], mf.t, grid2[i][j] - '0');
            mf.add_edge(idx(0, i, j), target_node[idx(0, i, j)], INF);
        }
    }

    int dx[] = {1, 0, 0, -1}, dy[] = {0, 1, -1, 0};
    for (int t = 1; t <= T; ++t) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
                for (int d = 0; d < 4; ++d) {
                    int ni = i + dx[d], nj = j + dy[d];
                    if (ni >= 1 && ni <= n && nj >= 1 && nj <= n &&
                        grid1[ni][nj] != 'Y' && grid1[ni][nj] != 'Z' &&
                        dist_grid[i][j] >= t && dist_grid[ni][nj] >= t) {
                        mf.add_edge(idx(t - 1, ni, nj), idx(t, i, j), INF);
                    }
                }
                mf.add_edge(idx(t, i, j), target_node[idx(0, i, j)], INF);
            }
        }
    }

    cout << mf.max_flow() << '\n';
    return 0;
}
